export type Change = {
  kind: "missing" | "damage" | "dirt";
  item: string;
  /** What the image edit was asked to do; used when reviewing labels. */
  detail: string;
  /** A finding counts as this change if its item or description mentions one of these. */
  match: string[];
  /** The price-list id a correct finding should carry. */
  price: string;
};

type EditSpec = {
  id: string;
  scene: string;
  instruction: string;
  changes: Change[];
  session: SessionShift;
  /** Side effects of the image edit found on review; findings about them are neither right nor wrong. */
  incidental?: string[];
};
type SessionShift = "none" | "light" | "pose";

